import { config } from '../config/index.js';

export interface CulqiChargeResponse {
  success: boolean;
  chargeId: string;
  amount: number;
  currency: string;
  status: string;
  message?: string;
  raw?: any;
}

export class CulqiService {
  private secretKey: string;
  private apiUrl: string;

  constructor() {
    this.secretKey = config.culqi.secretKey;
    this.apiUrl = config.culqi.apiUrl;
  }

  /**
   * Process a card charge using a token generated by Culqi Checkout
   * @param tokenId Token generated on the frontend (e.g. tok_test_xxx)
   * @param email Customer's email
   * @param amountPEN Amount in Peruvian Soles (e.g. 1.00)
   * @param description Brief transaction description
   * @param metadata Custom metadata (orderId, customer details)
   */
  async processCardCharge(
    tokenId: string,
    email: string,
    amountPEN: number,
    description: string,
    metadata: Record<string, any> = {}
  ): Promise<CulqiChargeResponse> {
    const amountInCentimos = Math.round(amountPEN * 100);

    // If real Culqi keys are set, call official Culqi API
    if (this.secretKey && !this.secretKey.includes('sample')) {
      try {
        const response = await fetch(`${this.apiUrl}/charges`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${this.secretKey}`
          },
          body: JSON.stringify({
            amount: amountInCentimos,
            currency_code: 'PEN',
            email,
            source_id: tokenId,
            description,
            metadata
          })
        });

        const data: any = await response.json();

        if (!response.ok) {
          return {
            success: false,
            chargeId: '',
            amount: amountPEN,
            currency: 'PEN',
            status: 'failed',
            message: data.user_message || data.merchant_message || 'Error al procesar con Culqi',
            raw: data
          };
        }

        return {
          success: true,
          chargeId: data.id,
          amount: data.amount / 100,
          currency: data.currency_code,
          status: 'paid',
          raw: data
        };
      } catch (err: any) {
        return {
          success: false,
          chargeId: '',
          amount: amountPEN,
          currency: 'PEN',
          status: 'error',
          message: err.message
        };
      }
    }

    // Default Sandbox Simulator (ideal for testing immediately without waiting for API keys)
    const simulatedChargeId = `chr_test_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
    return {
      success: true,
      chargeId: simulatedChargeId,
      amount: amountPEN,
      currency: 'PEN',
      status: 'paid',
      message: 'Cargo simulado exitosamente en Culqi Sandbox Perú'
    };
  }

  /**
   * Process a Yape transaction in Peru
   */
  async processYapeCharge(
    phoneNumber: string,
    otpCode: string,
    amountPEN: number,
    email: string
  ): Promise<CulqiChargeResponse> {
    const simulatedChargeId = `yape_test_${Date.now()}`;
    return {
      success: true,
      chargeId: simulatedChargeId,
      amount: amountPEN,
      currency: 'PEN',
      status: 'paid',
      message: `Aprobación Yape confirmada para el número ${phoneNumber} con OTP ${otpCode}`
    };
  }

  /**
   * Generate PagoEfectivo CIP Code
   */
  generateCIPCode(amountPEN: number): { cip: string; expiresAt: string } {
    const cip = `${Math.floor(1000 + Math.random() * 9000)} ${Math.floor(1000 + Math.random() * 9000)}`;
    const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
    return { cip, expiresAt };
  }
}

export const culqiService = new CulqiService();
